cases.base:
export function page(items: number[], index: number, size: number) {
  const start = index * size;
  const end = start + size;
  return items.slice(start, end);
}

cases.head:
export function page(items: number[], index: number, size: number) {
  const start = index * size;
  const end = start + size - 1;
  return items.slice(start, end);
}

