cases.base:
export function bounded(items: number[], offset: number, size: number) {
  return items.slice(offset, Math.min(items.length, offset + size));
}

cases.head:
export function bounded(items: number[], offset: number, size: number) {
  const end = Math.min(items.length, offset + size);
  return items.slice(offset, end);
}

cases.base:
